text(await tools.exec_command({cmd:"python3 -B - <<'PY'
import hashlib,json,subprocess
from pathlib import Path
rows=json.loads(Path('records.json').read_text())
latest={}
for row in rows:
    if row['id'] not in latest or row['revision']>latest[row['id']]['revision']:
        latest[row['id']]=row
active=[row for row in latest.values() if row['state']=='active']
report={'total':sum(row['amount'] for row in active),'ids':sorted(row['id'] for row in active)}
p=Path('output/report.json');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(report,indent=2)+'\n')
Path('evidence').mkdir(exist_ok=True)
command=['python3','-B','public_check.py']
r=subprocess.run(command,capture_output=True,text=True)
e={'command':command,'exit_status':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'report_sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
Path('evidence/report_contents.json').write_text(json.dumps(e,indent=2)+'\n')
print(json.dumps(e,indent=2))
assert r.returncode==0
actual=json.loads(p.read_text())
assert type(actual) is dict and set(actual)=={'total','ids'}
assert type(actual['total']) is int and type(actual['ids']) is list
assert all(type(x) is str for x in actual['ids']) and actual['ids']==sorted(actual['ids'])
shape={'check':'report_shape','status':'passed','method':'JSON parse; exact keys; type(total) is int; ids list of strings lexicographically sorted.','report_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'actual':actual}
Path('evidence/report_shape.json').write_text(json.dumps(shape,indent=2)+'\n')
print(json.dumps(shape,indent=2))
